components.css:
.ds-button-primary { display: inline-flex; min-height: 3.125rem; align-items: center; justify-content: center; gap: .625rem; border: 1px solid transparent; border-radius: 100vmax; padding: .625rem 1.25rem; background: var(--primary, #f6b7ce); color: var(--primary-foreground, #28182a); font: 700 .9375rem / 1.5 var(--font-inter, "Inter"), sans-serif; cursor: pointer; transition: background-color 180ms ease-out, border-color 180ms ease-out, color 180ms ease-out; }
.ds-button-primary:not(:disabled):hover { background: #ffcede; }
.ds-button-primary:focus-visible { outline: 2px solid var(--ring, #ffb9d2); outline-offset: 3px; }
.ds-button-primary:disabled { opacity: .55; cursor: not-allowed; }

.ds-button-outline { display: inline-flex; min-height: 3.125rem; align-items: center; justify-content: center; gap: .625rem; border: 1px solid var(--border, #51405b); border-radius: 100vmax; padding: .625rem 1.25rem; background: var(--surface, #221a30); color: var(--foreground, #fff4ed); font: 700 .9375rem / 1.5 var(--font-inter, "Inter"), sans-serif; cursor: pointer; transition: background-color 180ms ease-out, border-color 180ms ease-out, color 180ms ease-out; }
.ds-button-outline:not(:disabled):hover { background: var(--primary-accent, #392942); border-color: var(--primary, #f6b7ce); }
.ds-button-outline:focus-visible { outline: 2px solid var(--ring, #ffb9d2); outline-offset: 3px; }
.ds-button-outline:disabled { opacity: .55; cursor: not-allowed; }

.ds-icon-button { box-sizing: border-box; display: inline-grid; width: 2.75rem; height: 2.75rem; place-items: center; border: 1px solid var(--border, #51405b); border-radius: 50%; background: var(--surface, #221a30); color: var(--foreground, #fff4ed); cursor: pointer; transition: background-color 180ms ease-out, border-color 180ms ease-out; }
.ds-icon-button:hover { border-color: var(--primary, #f6b7ce); background: var(--primary-accent, #392942); }
.ds-icon-button:focus-visible { outline: 2px solid var(--ring, #ffb9d2); outline-offset: 3px; }

.ds-prompt { position: relative; width: 100%; }
.ds-prompt-input { box-sizing: border-box; width: 100%; border: 1px solid var(--border, #51405b); border-radius: .5rem; padding: .75rem 6rem .75rem 1rem; background: var(--input, #1d172a); color: var(--foreground, #fff4ed); caret-color: var(--primary, #f6b7ce); font: 400 1rem / 1.5 var(--font-inter, "Inter"), sans-serif; transition: border-color 150ms; }
.ds-prompt-input::placeholder { color: var(--muted-foreground, #cebfce); }
.ds-prompt-input:focus { border-color: var(--primary, #f6b7ce); }
.ds-prompt-input:focus-visible { outline: 2px solid var(--ring, #ffb9d2); outline-offset: 3px; }
.ds-prompt-status { position: absolute; top: 50%; right: .75rem; display: flex; height: 1.75rem; align-items: center; border-radius: 100vmax; padding: 0 .75rem; transform: translateY(-50%); background: var(--primary-accent, #392942); color: var(--muted-foreground, #cebfce); font: 400 .75rem / 1 var(--font-inter, "Inter"), sans-serif; pointer-events: none; }

.ds-nav { background: #191525; border-bottom: 1px solid #352840; }
.ds-nav-inner { box-sizing: border-box; display: flex; min-height: 4.25rem; width: min(77rem, calc(100% - 2 * clamp(1.125rem, 4vw, 3.25rem))); margin-inline: auto; align-items: center; justify-content: space-between; gap: .75rem; padding-block: .75rem; }
.ds-wordmark { display: inline-flex; align-items: center; gap: .6rem; color: var(--foreground, #fff4ed); font: 900 clamp(1.375rem, 6vw, 1.75rem) / .94 var(--font-barlow, "Barlow Condensed"), sans-serif; letter-spacing: -.014em; text-decoration: none; text-transform: uppercase; white-space: nowrap; }
.ds-wordmark__mark { width: .95em; height: auto; flex-shrink: 0; }
.ds-wordmark:focus-visible { outline: 2px solid var(--ring, #ffb9d2); outline-offset: 3px; }
.ds-credits { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 0 .375rem; border: 1px solid var(--border, #51405b); border-radius: 100vmax; padding: .375rem .625rem; background: var(--surface, #221a30); color: var(--muted-foreground, #cebfce); font: 500 .65rem / 1.5 var(--font-inter, "Inter"), sans-serif; font-variant-numeric: tabular-nums; }
.ds-credits-item, .ds-credits-time { white-space: nowrap; }
.ds-credits-time { display: inline-flex; align-items: center; gap: .375rem; }
.ds-credits-time::before { width: .25rem; height: .25rem; border-radius: 50%; background: var(--primary, #f6b7ce); opacity: .8; content: ""; }
.ds-credits strong { color: var(--primary, #f6b7ce); font-weight: 700; }
@media (min-width: 40rem) { .ds-credits { padding-inline: .75rem; font-size: .75rem; } }

.ds-credits { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 0 .375rem; border: 1px solid var(--border, #51405b); border-radius: 100vmax; padding: .375rem .625rem; background: var(--surface, #221a30); color: var(--muted-foreground, #cebfce); font: 500 .65rem / 1.5 var(--font-inter, "Inter"), sans-serif; font-variant-numeric: tabular-nums; }
.ds-credits-item, .ds-credits-time { white-space: nowrap; }
.ds-credits-time { display: inline-flex; align-items: center; gap: .375rem; }
.ds-credits-time::before { width: .25rem; height: .25rem; border-radius: 50%; background: var(--primary, #f6b7ce); opacity: .8; content: ""; }
.ds-credits strong { color: var(--primary, #f6b7ce); font-weight: 700; }
@media (min-width: 40rem) { .ds-credits { padding-inline: .75rem; font-size: .75rem; } }

.ds-plan { display: grid; gap: 1rem; border: 1px solid var(--border, #51405b); border-radius: .85rem; padding: clamp(1rem, 2vw, 1.55rem); background: var(--surface, #221a30); color: var(--foreground, #fff4ed); font: 400 .875rem / 1.5 var(--font-inter, "Inter"), sans-serif; }
.ds-plan-header { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: .25rem .75rem; }
.ds-plan-header h3 { margin: 0; font: 900 clamp(1.65rem, 2.7vw, 2.125rem) / .96 var(--font-barlow, "Barlow Condensed"), sans-serif; text-transform: uppercase; }
.ds-plan-header span { color: var(--muted-foreground, #cebfce); font-size: .75rem; font-weight: 500; }
.ds-plan-price { font: 900 2.5rem / 1 var(--font-barlow, "Barlow Condensed"), sans-serif; font-variant-numeric: tabular-nums; }
.ds-plan p { margin: 0; color: var(--muted-foreground, #cebfce); }
.ds-plan-button { display: inline-flex; min-height: 3.125rem; align-items: center; justify-content: center; gap: .625rem; border: 1px solid var(--border, #51405b); border-radius: 100vmax; padding: .625rem 1.25rem; background: var(--surface, #221a30); color: var(--foreground, #fff4ed); font: 700 .9375rem / 1.5 var(--font-inter, "Inter"), sans-serif; cursor: pointer; transition: background-color 180ms ease-out, border-color 180ms ease-out, color 180ms ease-out; }
.ds-plan-button:not(:disabled):hover { background: var(--primary-accent, #392942); border-color: var(--primary, #f6b7ce); }
.ds-plan-button:focus-visible { outline: 2px solid var(--ring, #ffb9d2); outline-offset: 3px; }
.ds-plan-button:disabled { opacity: .55; cursor: not-allowed; }

.ds-style-picker { min-width: 0; margin: 0; border: 0; padding: 0; }
.ds-style-picker legend { margin-bottom: .625rem; color: var(--primary, #f6b7ce); font: 700 .75rem / 1rem var(--font-inter, "Inter"), sans-serif; letter-spacing: .11em; text-transform: uppercase; }
.ds-style-row { display: flex; gap: .55rem; overflow-x: auto; margin: -.2rem; padding: .2rem; scrollbar-width: thin; }
.ds-style-option { box-sizing: border-box; position: relative; display: flex; min-width: 5rem; flex: 1 0 calc((100% - 1.1rem) / 3); flex-direction: column; overflow: hidden; border: 1px solid var(--border, #51405b); border-radius: .65rem; background: #20182d; color: var(--foreground, #fff4ed); cursor: pointer; transition: background-color 180ms ease-out, border-color 180ms ease-out; }
.ds-style-option:hover { border-color: #b492bb; }
.ds-style-option:has(:checked) { border-color: var(--primary, #f6b7ce); background: var(--primary, #f6b7ce); color: var(--primary-foreground, #28182a); }
.ds-style-option:has(:focus-visible) { outline: 2px solid var(--ring, #ffb9d2); outline-offset: 1px; }
.ds-style-radio { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.ds-style-image { position: relative; aspect-ratio: 1.48; }
.ds-style-image img { position: absolute; width: 100%; height: 100%; object-fit: cover; object-position: center 27%; }
.ds-style-option:first-child img { object-position: top; }
.ds-style-name { padding: .45rem .55rem .5rem; font: 700 clamp(.75rem, 2.8vw, .875rem) / 1.3 var(--font-inter, "Inter"), sans-serif; }

.ds-upload { display: flex; width: 100%; }
.ds-upload-target { box-sizing: border-box; display: flex; width: 100%; min-height: 4.875rem; align-items: center; justify-content: center; gap: .75rem; border: 1px dashed #a87f9c; border-radius: .75rem; padding: .85rem; background: #251934; color: var(--foreground, #fff4ed); font: 700 .9375rem / 1.5 var(--font-inter, "Inter"), sans-serif; text-align: center; cursor: pointer; transition: background-color 180ms ease-out, border-color 180ms ease-out; }
.ds-upload-target:hover { background: #382641; border-color: var(--primary, #f6b7ce); }
.ds-upload-target:has(:focus-visible) { outline: 2px solid var(--ring, #ffb9d2); outline-offset: 1px; }
.ds-upload-input { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.ds-upload-icon { display: grid; width: 2.5rem; height: 2.5rem; flex: none; place-items: center; border-radius: 50%; background: var(--primary, #f6b7ce); color: #000; }
.ds-upload-desktop { display: none; }
@media (min-width: 48rem) { .ds-upload-desktop { display: inline; } .ds-upload-mobile { display: none; } }
